### 🖼️ 2. **View** – Handles UI and user input

```javascript
class TodoView {
    constructor() {
        this.input = document.getElementById('todo-input');
        this.addButton = document.getElementById('add-button');
        this.todoList = document.getElementById('todo-list');

        this.addButton.addEventListener('click', this.addTodo.bind(this));
        this.input.addEventListener('keypress', (e) => {
            if (e.key === 'Enter') this.addTodo();
        });
    }

    addTodo() {
        const text = this.input.value.trim();
        if (text !== '') {
            this.presenter.addTodo(text);
            this.input.value = '';
        }
    }

    renderTodos(todos) {
        this.todoList.innerHTML = '';
        todos.forEach(todo => {
            const li = document.createElement('li');
            li.className = todo.completed ? 'completed' : '';
            li.innerHTML = `
                <span>${todo.text}</span>
                <button class="toggle">✔</button>
                <button class="delete">✖</button>
            `;

            const toggleBtn = li.querySelector('.toggle');
            const deleteBtn = li.querySelector('.delete');

            toggleBtn.addEventListener('click', () => this.presenter.toggleTodo(todo.id));
            deleteBtn.addEventListener('click', () => this.presenter.removeTodo(todo.id));

            this.todoList.appendChild(li);
        });
    }
}
```

